.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

/* ── Label ── */
.form-field label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-label);
  display: flex;
  align-items: center;
  gap: 0.25rem;
