.required-marker {
  color: #ff8088;
  font-size: 0.9em;
  line-height: 1;
}

/* ── Inputs ── */
.form-field input {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-primary);
  font-size: 1rem;
  font-family: inherit;
  padding: 0.65rem 0.875rem;
  width: 100%;
  transition: border-color var(--transition), background var(--transition),
