.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(255, 95, 109, 0.22);
  border-color: var(--border-error);
}

.form-field.is-valid input {
  border-color: var(--border-success);
}

/* ── Helper and error text ── */
.field-helper,
.field-error {
  font-size: 0.8rem;
  line-height: 1.4;
  padding-left: 0.125rem;
}

.field-helper {
  color: var(--helper-text);
}

.field-error {
  color: var(--error-text);
  display: none;
  align-items: flex-start;
  gap: 0.3rem;
}

.field-error[aria-hidden="false"],
.field-error:not([aria-hidden]) {
  display: flex;
}

.field-error svg {
  flex-shrink: 0;
  margin-top: 0.1em;
}

/* ── Submit button ── */
.btn-submit {
  margin-top: 0.5rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  padding: 0.75rem 1.5rem;
  cursor: pointer;
  width: 100%;
  transition: background var(--transition), box-shadow var(--transition),
              transform 0.1s ease;
  letter-spacing: 0.01em;
}

.btn-submit:hover:not(:disabled) {
  background: var(--accent-hover);
  box-shadow: 0 4px 18px rgba(108, 142, 255, 0.35);
}

.btn-submit:active:not(:disabled) {
  background: var(--accent-active);
  transform: translateY(1px);
}

.btn-submit:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 3px;
}

.btn-submit:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

