+    { id: "fullName",  inputId: "input-fullName",  errorId: "error-fullName" },
+    { id: "email",     inputId: "input-email",      errorId: "error-email"    },
+    { id: "phone",     inputId: "input-phone",      errorId: "error-phone"    },
+  ];
+
+  /* ── State ── */
+  const touched = { fullName: false, email: false, phone: false };
+
+  /* ── DOM helpers ── */
+  function getInput(fieldId)  { return document.getElementById(`input-${fieldId}`);  }
+  function getError(fieldId)  { return document.getElementById(`error-${fieldId}`);  }
+  function getWrapper(fieldId){ return getInput(fieldId)?.closest(".form-field");     }
+
+  function setError(fieldId, message) {
+    const input   = getInput(fieldId);
+    const errorEl = getError(fieldId);
+    const wrapper = getWrapper(fieldId);
+    if (!input || !errorEl || !wrapper) return;
+
+    if (message) {
+      input.setAttribute("aria-invalid", "true");
+      errorEl.querySelector(".error-text").textContent = message;
+      errorEl.setAttribute("aria-hidden", "false");
+      errorEl.style.display = "flex";
+      wrapper.classList.remove("is-valid");
+    } else {
+      input.setAttribute("aria-invalid", "false");
+      errorEl.setAttribute("aria-hidden", "true");
+      errorEl.style.display = "none";
+      // only mark valid when there's actual content
+      if (input.value.trim()) {
+        wrapper.classList.add("is-valid");
+      } else {
+        wrapper.classList.remove("is-valid");
+      }
+    }
+  }
+
+  function validateField(fieldId) {
+    const input = getInput(fieldId);
+    if (!input) return null;
+    const error = VALIDATORS[fieldId]?.(input.value) ?? null;
+    setError(fieldId, error);
+    return error;
+  }
+
+  /* ── Wire up live validation (on blur + on input after touched) ── */
+  FIELDS.forEach(({ id: fieldId }) => {
+    const input = getInput(fieldId);
+    if (!input) return;
+
+    input.addEventListener("blur", () => {
+      touched[fieldId] = true;
+      validateField(fieldId);
+    });
+
+    input.addEventListener("input", () => {
+      if (touched[fieldId]) validateField(fieldId);
+    });
+  });
+
+  /* ── Status banner ── */
+  function showBanner(type, message) {
+    const banner = document.getElementById("form-status");
+    if (!banner) return;
+    banner.className = `status-banner ${type} visible`;
+    banner.querySelector(".banner-text").textContent = message;
+  }
+
+  function hideBanner() {
+    const banner = document.getElementById("form-status");
+    if (!banner) return;
+    banner.className = "status-banner";
+  }
+
+  /* ── Submit ── */
+  document.getElementById("contact-form")?.addEventListener("submit", (e) => {
+    e.preventDefault();
+    hideBanner();
+
+    // Validate all fields and collect errors
+    FIELDS.forEach(({ id }) => { touched[id] = true; });
+    const errors = FIELDS.map(({ id }) => ({ id, error: validateField(id) }))
+                         .filter(({ error }) => error !== null);
+
+    if (errors.length > 0) {
+      // Focus first invalid field
+      const firstErrorId = errors[0].id;
+      getInput(firstErrorId)?.focus();
+      showBanner("error", "Please fix the errors below before submitting.");
+      return;
+    }
+
+    // Simulate submission
+    const btn = document.getElementById("submit-btn");
+    btn.disabled = true;
+    btn.textContent = "Sending…";
+
+    setTimeout(() => {
+      btn.disabled = false;
+      btn.textContent = "Send Message";
+      showBanner("success", "Your message has been sent! We'll get back to you shortly.");
+      document.getElementById("contact-form").reset();
+      FIELDS.forEach(({ id }) => {
+        touched[id] = false;
+        setError(id, null);
+        getWrapper(id)?.classList.remove("is-valid");
+      });
+    }, 1200);
+  });
+})();
